		if host != "" {
			r.ClusterHost = coreapi.NewOptString(host)
		}
		if path != "" {
			r.Path = coreapi.NewOptString(path)
		}
		return r
	}

	t.Run("builds the URL from the server's clusterHost and path", func(t *testing.T) {
