// hint about the accepted shapes.
func parseNativeCloneRef(ref string) (project, repo string, ok bool) {
	segs := strings.Split(strings.TrimPrefix(strings.TrimSpace(ref), "/"), "/")
	if len(segs) == 3 && segs[0] == nativeCloneForge {
